// Raindrops

let size, x, y, width, spacingX, spacingY;

function setup() {
	size = min(windowWidth, windowHeight, 500);
	createCanvas(size, size);
	// noLoop() removed for animation
}

function draw() {
	background(255);
	noStroke();
	spacingX = round(size / 20);
	spacingY = spacingX * 2 / cos(PI / 6);
	for (var i = 0; i < size * 10; i++) {
		let m = map(i, size * 2.5, size * 10, 0, 75);
		fill(random(255), random(255), random(255), 255 - m);
		x = round(random(size / spacingX)) * spacingX;
		y = round(random(size / (spacingY / 4))) * (spacingY / 4);
		width = [spacingX, spacingX * 2][i % 2];
		hexagon(x, y, width);
	}
	frame(size, spacingX * 0.75);
}

function hexagon(x, y, width) {
	let rad = width / cos(PI / 6);
	beginShape();
	for (var i = 0; i < 6; i++) {
		let angle = i * 2 * PI / 6 + PI / 6;
		vertex(x + rad * cos(angle), y + rad * sin(angle));		
	}
	endShape();
}

function frame(size, thickness) {
	let r = random(155, 255);
	let g = random(155, 255);
	let b = random(155, 150);
	fill(r, g, b);
	noStroke();
	rect(0, 0, thickness, size);
	rect(size - thickness, 0, thickness, size);
	rect(0, 0, size, thickness);
	rect(0, size - thickness, size, thickness);	

	fill(r, g, b, 50);
	rect(0, 0, size, size);
}

function mouseClicked() {
	redraw();
}
